source = '''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    barriers = [r for r in range(h) if all(v == 2 for v in g[r])]
    if barriers:
        barrier = barriers[0]
        dr = 1 if barrier == 0 else -1
    else:
        barriers = [c for c in range(w) if all(g[r][c] == 2 for r in range(h))]
        if not barriers:
            return g
        barrier = barriers[0]
        dr = 0
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color in (0, 2) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and g[nr][nc] == color and (nr,nc) not in seen:
                        seen.add((nr,nc)); stack.append((nr,nc))
            objects.append([color, cells])
    # Fall toward a full horizontal barrier, moving each rigid object by one cell per round.
    occupied = {cell: i for i, (_, cells) in enumerate(objects) for cell in cells}
    while True:
        movable = []
        for i, (_, cells) in enumerate(objects):
            dest = [(r + dr, c) for r, c in cells]
            if any(r < 0 or r >= h or c < 0 or c >= w for r, c in dest):
                continue
            if all((r, c) not in occupied or occupied[(r, c)] == i for r, c in dest) and all(g[r][c] != 2 for r,c in dest):
                movable.append(i)
        if not movable:
            break
        for i in movable:
            for cell in objects[i][1]:
                occupied.pop(cell)
        for i in movable:
            color, cells = objects[i]
            objects[i][1] = [(r + dr, c) for r, c in cells]
            for cell in objects[i][1]:
                occupied[cell] = i
    out = [[0 for _ in range(w)] for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if g[r][c] == 2:
                out[r][c] = 2
    for color, cells in objects:
        for r, c in cells:
            out[r][c] = color
    return out
'''
